import java.util.*;
import java.io.*;

public class p1096g_v2 {
    private static final long MOD = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        long[] base = new long[10];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; i++) {
            base[Integer.parseInt(st.nextToken())] = 1;
        }
        long[] result = power(base, n >>> 1);
        long sum = 0;
        for (long x : result) {
            sum = (sum + (x * x) % MOD) % MOD;
        }
        System.out.println(sum);
    }

    private static long[] power(long[] base, long exponent) {
        if (exponent == 1) return base;
        if ((exponent & 1) == 1) {
            return FFT.multiplyPrecise(base, power(base, exponent - 1));
        }
        long[] half = power(base, exponent >> 1);
        return FFT.multiplyPrecise(half, half);
    }

    static class FFT {
        private static final int MAX_K = 23;
        private static final int MAX_N = 1 << MAX_K;
        private static final double[] wR = new double[MAX_N];
        private static final double[] wI = new double[MAX_N];
        private static final double[] aR = new double[MAX_N];
        private static final double[] aI = new double[MAX_N];
        private static int n, k, lastK = -1;
        private static final int[] bitReverse = new int[MAX_N];

        private static void prepare(int size) {
            n = size;
            k = 0;
            while ((1 << k) < n) k++;
            if (lastK != k) {
                lastK = k;
                bitReverse[0] = 0;
                for (int i = 1, g = -1; i < n; i++) {
                    if ((i & (i - 1)) == 0) g++;
                    bitReverse[i] = bitReverse[i ^ (1 << g)] ^ (1 << (k - 1 - g));
                }
                wR[1] = 1;
                wI[1] = 0;
                for (int t = 0; t < k - 1; t++) {
                    double angle = Math.PI / (1 << k) * (1 << (k - 1 - t));
                    double cosVal = Math.cos(angle);
                    double sinVal = Math.sin(angle);
                    int step = 1 << t;
                    for (int j = step, idx = step * 2; j < step * 2; j++, idx += 2) {
                        wR[idx] = wR[j];
                        wI[idx] = wI[j];
                        wR[idx + 1] = wR[j] * cosVal - wI[j] * sinVal;
                        wI[idx + 1] = wR[j] * sinVal + wI[j] * cosVal;
                    }
                }
            }
        }

        private static void transform(boolean inverse) {
            for (int i = 0; i < n; i++) {
                int j = bitReverse[i];
                if (i < j) {
                    double tmp = aR[i];
                    aR[i] = aR[j];
                    aR[j] = tmp;
                    tmp = aI[i];
                    aI[i] = aI[j];
                    aI[j] = tmp;
                }
            }
            if (inverse) {
                for (int i = 0; i < n; i++) aI[i] = -aI[i];
            }
            for (int len = 1; len < n; len <<= 1) {
                for (int i = 0; i < n; i += len << 1) {
                    for (int j = 0; j < len; j++) {
                        int idx = len + j;
                        double tr = aR[i + len + j] * wR[idx] - aI[i + len + j] * wI[idx];
                        double ti = aR[i + len + j] * wI[idx] + aI[i + len + j] * wR[idx];
                        aR[i + len + j] = aR[i + j] - tr;
                        aI[i + len + j] = aI[i + j] - ti;
                        aR[i + j] += tr;
                        aI[i + j] += ti;
                    }
                }
            }
        }

        static long[] multiply(long[] a, long[] b) {
            int lenA = a.length, lenB = b.length;
            int size = 1;
            while (size < lenA + lenB - 1) size <<= 1;
            prepare(size);
            for (int i = 0; i < size; i++) {
                aR[i] = i < lenA ? a[i] : 0;
                aI[i] = i < lenB ? b[i] : 0;
            }
            transform(false);
            aR[size] = aR[0];
            aI[size] = aI[0];
            double factor = -0.25 / size;
            for (int i = 0; i <= size - i; i++) {
                double r1 = aR[i], i1 = aI[i];
                double r2 = aR[size - i], i2 = aI[size - i];
                double real = r1 * r1 - i1 * i1 - (r2 * r2 - i2 * i2);
                double imag = 2 * r1 * i1 + 2 * r2 * i2;
                aR[i] = -imag * factor;
                aI[i] = real * factor;
                aR[size - i] = aR[i];
                aI[size - i] = -aI[i];
            }
            transform(true);
            long[] res = new long[lenA + lenB - 1];
            for (int i = 0; i < res.length; i++) res[i] = Math.round(aR[i]) % MOD;
            return res;
        }

        static long[] multiplyPrecise(long[] x, long[] y) {
            long base = (long) Math.sqrt(MOD);
            long[] xl = new long[x.length];
            long[] xh = new long[x.length];
            long[] yl = new long[y.length];
            long[] yh = new long[y.length];
            for (int i = 0; i < x.length; i++) {
                xl[i] = x[i] % base;
                xh[i] = x[i] / base;
            }
            for (int i = 0; i < y.length; i++) {
                yl[i] = y[i] % base;
                yh[i] = y[i] / base;
            }
            long[] p11 = multiply(xl, yl);
            long[] p12 = multiply(xl, yh);
            long[] p21 = multiply(xh, yl);
            long[] p22 = multiply(xh, yh);
            long[] res = new long[p11.length];
            for (int i = 0; i < res.length; i++) {
                long term1 = (base * base % MOD) * p22[i] % MOD;
                long term2 = base * ((p12[i] + p21[i]) % MOD) % MOD;
                res[i] = (term1 + term2 + p11[i]) % MOD;
            }
            return res;
        }
    }
}
